DO $$ DECLARE p uuid:='00000000-0000-4000-8000-000000000020'; p2 uuid:='00000000-0000-4000-8000-000000000021'; m uuid:='00000000-0000-4000-8000-000000000030'; d uuid; d2 uuid; a jsonb; ts timestamptz; u uuid:=gen_random_uuid(); intent jsonb; BEGIN
 PERFORM set_config('test.actor','00000000-0000-4000-8000-000000000002',true);
 BEGIN PERFORM public.platform_product_dossier_management_create(p,m); RAISE EXCEPTION 'tenant accepted'; EXCEPTION WHEN insufficient_privilege THEN RAISE NOTICE 'PASS tenant admin denied'; END;
 PERFORM set_config('test.actor','00000000-0000-4000-8000-000000000001',true);
 BEGIN PERFORM public.platform_product_dossier_management_create(p,'00000000-0000-4000-8000-000000000032'); RAISE EXCEPTION 'foreign accepted'; EXCEPTION WHEN insufficient_privilege THEN RAISE NOTICE 'PASS foreign microorganism denied'; END;
 BEGIN PERFORM public.platform_product_dossier_management_create(p,NULL); RAISE EXCEPTION 'null accepted'; EXCEPTION WHEN invalid_parameter_value THEN RAISE NOTICE 'PASS explicit choice required'; END;
 IF jsonb_array_length(public.platform_product_dossier_management_context(p)->'microorganisms')<>2 THEN RAISE EXCEPTION 'multi links'; END IF; RAISE NOTICE 'PASS multi-micro context';
 a:=public.platform_product_dossier_management_create(p,m); d:=(a->>'dossier_id')::uuid;
 IF public.platform_product_dossier_management_create(p,m) IS DISTINCT FROM a THEN RAISE EXCEPTION 'duplicate'; END IF; RAISE NOTICE 'PASS idempotent draft';
 BEGIN PERFORM public.platform_product_dossier_management_create(p,'00000000-0000-4000-8000-000000000031'); RAISE EXCEPTION 'choice changed'; EXCEPTION WHEN SQLSTATE 'PT409' THEN RAISE NOTICE 'PASS immutable choice'; END;
 d2:=(public.platform_product_dossier_management_create(p2,m)->>'dossier_id')::uuid; IF d=d2 THEN RAISE EXCEPTION 'shared dossier'; END IF; RAISE NOTICE 'PASS shared micro distinct products';
 IF public.fn_microorganism_regulatory_facts(m) IS NOT NULL THEN RAISE EXCEPTION 'legacy inherited'; END IF; RAISE NOTICE 'PASS legacy separated';
 SELECT updated_at INTO ts FROM public.microorganism_regulatory_dossiers WHERE id=d;
 PERFORM public.platform_product_dossier_management_save(p,d,ts,'{"notes":"Synthetic QA"}');
 IF (SELECT notes FROM public.microorganism_regulatory_dossiers WHERE id=d)<>'Synthetic QA' THEN RAISE EXCEPTION 'not saved'; END IF; RAISE NOTICE 'PASS save';
 BEGIN PERFORM public.platform_product_dossier_management_save(p,d,ts,'{}'); RAISE EXCEPTION 'stale accepted'; EXCEPTION WHEN SQLSTATE 'PT409' THEN RAISE NOTICE 'PASS CAS'; END;
 SELECT updated_at INTO ts FROM public.microorganism_regulatory_dossiers WHERE id=d;
 BEGIN PERFORM public.platform_product_dossier_management_checklist(p,d,ts,'CEPA','NOT_APPLICABLE',NULL); RAISE EXCEPTION 'missing justification'; EXCEPTION WHEN invalid_parameter_value THEN RAISE NOTICE 'PASS justification required'; END;
 PERFORM public.platform_product_dossier_management_checklist(p,d,ts,'CEPA','CONFIRMED','QA'); RAISE NOTICE 'PASS checklist changed';
 SELECT updated_at INTO ts FROM public.microorganism_regulatory_dossiers WHERE id=d;
 intent:=jsonb_build_object('filename','qa.pdf','size_bytes',8,'sha256',repeat('a',64),'mime','application/pdf','title','QA','doc_type','LAUDO');
 a:=public.platform_product_dossier_upload_prepare(p,d,ts,u,intent);
 IF public.platform_product_dossier_upload_prepare(p,d,ts,u,intent) IS DISTINCT FROM a THEN RAISE EXCEPTION 'reservation duplicate'; END IF; RAISE NOTICE 'PASS reservation idempotent';
 BEGIN PERFORM public.platform_product_dossier_upload_finalize(u); RAISE EXCEPTION 'unverified accepted'; EXCEPTION WHEN object_in_use THEN RAISE NOTICE 'PASS unverified bytes denied'; END;
 BEGIN PERFORM public.platform_product_dossier_management_submit(p,d,ts); RAISE EXCEPTION 'pending accepted'; EXCEPTION WHEN object_in_use THEN RAISE NOTICE 'PASS pending upload blocks submit'; END;
 BEGIN PERFORM public.platform_product_dossier_upload_attest(u,repeat('a',64),8,'application/pdf'); RAISE EXCEPTION 'caller attested'; EXCEPTION WHEN insufficient_privilege THEN RAISE NOTICE 'PASS caller cannot attest'; END;
 PERFORM set_config('test.service','true',true); PERFORM public.platform_product_dossier_upload_attest(u,repeat('a',64),8,'application/pdf');
 INSERT INTO storage.objects VALUES('fiscal-regulatorio',a->>'storage_path');
 PERFORM public.platform_product_dossier_upload_finalize(u); PERFORM public.platform_product_dossier_upload_finalize(u);
 IF (SELECT count(*) FROM public.microorganism_regulatory_documents WHERE dossier_id=d)<>1 THEN RAISE EXCEPTION 'duplicate document'; END IF; RAISE NOTICE 'PASS document finalize once';
 BEGIN PERFORM public.platform_product_dossier_upload_cancel_begin(u); RAISE EXCEPTION 'committed cancellation accepted'; EXCEPTION WHEN insufficient_privilege THEN RAISE NOTICE 'PASS committed document cannot cancel'; END;
 SELECT updated_at INTO ts FROM public.microorganism_regulatory_dossiers WHERE id=d;
 u:=gen_random_uuid(); intent:=jsonb_set(intent,'{sha256}',to_jsonb(repeat('b',64)));
 PERFORM public.platform_product_dossier_upload_prepare(p,d,ts,u,intent);
 PERFORM public.platform_product_dossier_upload_cancel_begin(u);
 BEGIN PERFORM public.platform_product_dossier_upload_finalize(u); RAISE EXCEPTION 'cancelling finalized'; EXCEPTION WHEN object_in_use THEN RAISE NOTICE 'PASS cancellation excludes finalize'; END;
 PERFORM public.platform_product_dossier_upload_cancel(u);
 IF (SELECT state FROM platform_private.product_dossier_uploads WHERE id=u)<>'CANCELLED' THEN RAISE EXCEPTION 'cancel'; END IF; RAISE NOTICE 'PASS cancelled reservation tracked';
 BEGIN UPDATE public.microorganism_regulatory_dossiers SET notes='bypass' WHERE id=d; RAISE EXCEPTION 'direct accepted'; EXCEPTION WHEN insufficient_privilege THEN RAISE NOTICE 'PASS direct write denied'; END;
 SELECT updated_at INTO ts FROM public.microorganism_regulatory_dossiers WHERE id=d;
 PERFORM public.platform_product_dossier_management_submit(p,d,ts); IF (SELECT status FROM public.microorganism_regulatory_dossiers WHERE id=d)<>'PENDING_REVIEW' THEN RAISE EXCEPTION 'submit'; END IF; RAISE NOTICE 'PASS legitimate submission';
 IF EXISTS(SELECT 1 FROM platform_private.product_dossier_write_permits) THEN RAISE EXCEPTION 'permit residual'; END IF; RAISE NOTICE 'PASS zero residual permits';
 INSERT INTO platform_private.product_dossier_write_permits VALUES(txid_current(),d2);
 UPDATE public.microorganism_regulatory_dossiers SET status='VALIDATED' WHERE id=d2;
 DELETE FROM platform_private.product_dossier_write_permits WHERE txid=txid_current() AND dossier_id=d2;
 SELECT updated_at INTO ts FROM public.microorganism_regulatory_dossiers WHERE id=d2;
 BEGIN PERFORM public.platform_product_dossier_management_save(p2,d2,ts,'{"notes":"forbidden"}'); RAISE EXCEPTION 'published accepted'; EXCEPTION WHEN object_in_use THEN RAISE NOTICE 'PASS published dossier locked'; END;
END $$;
